CLASS_DEF = [
("1","Confirmed financing reliance","An executed financing document names the firm as IE (or requires its report) AND grants named lenders/agents rights to rely on its work (reliance letter, report addressed to lenders, or IE certificate addressed to the agent). Note: signed reliance letters themselves were not sighted; classification rests on executed agreement terms."),
("2","Named financing assignment","The firm is publicly identified as IE/technical adviser for a specific financing or transaction, but formal lender reliance is not independently established (often company- or sponsor-reported)."),
("3","Contractual eligibility","The firm is expressly identified as an acceptable/approved IE in a financing agreement."),
("4","Documented lender-facing experience","Evidence of project-finance IE work for lenders/investors without named transactions or named relying parties."),
("5","Company-reported or adjacent","Marketing claims or relevant engineering capability without verified financing assignments."),
]

